<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/services_v1380.php';$p=sk1380_require_provider();$ent=sk1380_entitlements((int)$p['id']);$fastEffective=!empty($ent['fast_service'])&&!empty($p['fast_service_enabled']);$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{sk1380_csrf_check();$act=(string)$_POST['action'];if($act==='save_service'){$id=(int)($_POST['id']??0);$cid=(int)$_POST['category_id'];$title=trim((string)$_POST['title']);$desc=trim((string)($_POST['description']??''));$price=max(0,(float)($_POST['base_price']??0));$unit=in_array($_POST['price_unit']??'job',['job','hour','visit','item','day'],true)?$_POST['price_unit']:'job';$fast=!empty($_POST['fast_available'])?1:0;if($fast&&!$ent['fast_service'])throw new RuntimeException('Fast Service is not included in your active package.');if(!$id){$q=sk1380_db()->prepare('SELECT COUNT(*) FROM service_offerings_v1380 WHERE tenant_id=? AND provider_id=?');$q->execute([sk1380_tid(),$p['id']]);if((int)$q->fetchColumn()>=$ent['service_limit'])throw new RuntimeException('Your package service limit has been reached.');}$allowed=array_column(sk1380_provider_categories((int)$p['id']),'id');if(!in_array($cid,$allowed))throw new RuntimeException('This category is not approved on your provider profile.');if($title==='')throw new RuntimeException('Service title is required.');$slug=sk1380_slug($title).'-'.$p['id'].'-'.substr(md5((string)microtime(true)),0,6);if($id){sk1380_db()->prepare('UPDATE service_offerings_v1380 SET category_id=?,title=?,description=?,base_price=?,price_unit=?,fast_available=?,active=?,updated_at=NOW() WHERE tenant_id=? AND provider_id=? AND id=?')->execute([$cid,$title,$desc?:null,$price,$unit,$fast,!empty($_POST['active'])?1:0,sk1380_tid(),$p['id'],$id]);}else{sk1380_db()->prepare('INSERT INTO service_offerings_v1380(tenant_id,provider_id,category_id,title,slug,description,base_price,price_unit,fast_available,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,1,NOW(),NOW())')->execute([sk1380_tid(),$p['id'],$cid,$title,$slug,$desc?:null,$price,$unit,$fast]);}$msg='Service saved.';}elseif($act==='profile'){$fast=!empty($_POST['fast'])?1:0;if($fast&&!$ent['fast_service'])throw new RuntimeException('Upgrade to a package with Fast Service entitlement first.');sk1380_db()->prepare('UPDATE service_provider_profiles_v1380 SET display_name=?,business_name=?,bio=?,area=?,phone_public=?,fast_service_enabled=?,last_active_at=NOW(),updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([trim($_POST['display_name']),trim($_POST['business_name'])?:null,trim($_POST['bio'])?:null,trim($_POST['area']),trim($_POST['phone_public'])?:null,$fast,sk1380_tid(),$p['id']]);$msg='Provider profile updated.';} }catch(Throwable $e){$err=$e->getMessage();}}$p=sk1380_provider();$services=sk1380_provider_services((int)$p['id']);$editService=null;if((int)($_GET['edit']??0)>0)foreach($services as $es)if((int)$es['id']===(int)$_GET['edit']){$editService=$es;break;}$q=sk1380_db()->prepare('SELECT COUNT(*) FROM service_orders_v1380 WHERE tenant_id=? AND provider_id=? AND status IN("booked","accepted","on_the_way","started")');$q->execute([sk1380_tid(),$p['id']]);$active=(int)$q->fetchColumn();$q=sk1380_db()->prepare('SELECT COUNT(*) FROM service_requests_v1380 r WHERE r.tenant_id=? AND r.status IN("open","quoted") AND (r.preferred_provider_id IS NULL OR r.preferred_provider_id=?) AND (r.urgency<>"fast" OR ?=1) AND EXISTS(SELECT 1 FROM service_provider_categories_v1380 pc WHERE pc.tenant_id=r.tenant_id AND pc.provider_id=? AND pc.category_id=r.category_id) AND NOT EXISTS(SELECT 1 FROM service_quotes_v1380 sq WHERE sq.tenant_id=r.tenant_id AND sq.request_id=r.id AND sq.provider_id=?)');$q->execute([sk1380_tid(),$p['id'],$fastEffective?1:0,$p['id'],$p['id']]);$leads=(int)$q->fetchColumn();sk1380_shell('Provider Dashboard','provider-dashboard');?><section class="dash-hero"><div><span class="eyebrow">SERVICE PROVIDER PRO</span><h1><?=sk1380_h($p['business_name']?:$p['display_name'])?></h1><p><?=sk1380_h($p['package_name'])?> package · <?=number_format((float)$p['rating_avg'],1)?> ★</p></div><div class="hero-actions"><a href="/provider/service-requests.php"><?=$leads?> New Leads</a><a href="/provider/service-orders.php"><?=$active?> Active Jobs</a><a href="/provider/service-packages.php">Packages</a><a href="/provider/service-promotions.php">Promotions</a></div></section><?php if($msg):?><div class="notice ok"><?=sk1380_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1380_h($err)?></div><?php endif;?><div class="metric-grid"><article><span>Services</span><b><?=count($services)?> / <?=$ent['service_limit']?></b></article><article><span>Quotes this month</span><b><?=sk1380_month_quote_count((int)$p['id'])?> / <?=$ent['monthly_quote_limit']?></b></article><article><span>Fast Service</span><b><?=$ent['fast_service']?'Available':'Package locked'?></b></article><article><span>Search priority</span><b>+<?=$ent['priority_weight']?></b></article></div><div class="provider-workspace"><section><h2>Your Services</h2><div class="offering-grid"><?php foreach($services as $s):?><article><span><?=sk1380_h($s['icon'])?></span><h3><?=sk1380_h($s['title'])?></h3><b><?=sk1380_h(sk1380_price($s))?></b><small><?=sk1380_h($s['active']?'Live':'Hidden')?><?=$s['fast_available']?' · Fast':''?><?=!empty($s['featured_until'])&&strtotime($s['featured_until'])>time()?' · Featured':''?></small><a href="?edit=<?=$s['id']?>">Edit</a></article><?php endforeach;?></div><h2><?=$editService?'Edit service':'Add service'?></h2><form method="post" class="pro-form compact"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="action" value="save_service"><input type="hidden" name="id" value="<?=sk1380_h($editService['id']??0)?>"><div class="two"><label>Category<select name="category_id"><?php foreach(sk1380_provider_categories((int)$p['id']) as $c):?><option value="<?=$c['id']?>" <?=($editService&&$editService['category_id']==$c['id'])?'selected':''?>><?=sk1380_h($c['name'])?></option><?php endforeach;?></select></label><label>Service title<input name="title" required value="<?=sk1380_h($editService['title']??'')?>" placeholder="e.g. Home electrical fault repair"></label></div><label>Description<textarea name="description"><?=sk1380_h($editService['description']??'')?></textarea></label><div class="three"><label>Starting price<input type="number" min="0" name="base_price" value="<?=sk1380_h($editService['base_price']??0)?>"></label><label>Price unit<select name="price_unit"><?php foreach(['job'=>'Per job','visit'=>'Per visit','hour'=>'Per hour','item'=>'Per item','day'=>'Per day'] as $uk=>$ul):?><option value="<?=$uk?>" <?=($editService['price_unit']??'job')===$uk?'selected':''?>><?=$ul?></option><?php endforeach;?></select></label><label class="check"><input type="checkbox" name="fast_available" value="1" <?=!empty($editService['fast_available'])?'checked':''?>> Fast Service eligible</label></div><?php if($editService):?><label class="check"><input type="checkbox" name="active" value="1" <?=$editService['active']?'checked':''?>> Publicly active</label><?php endif;?><button><?=$editService?'Update Service':'Publish Service'?></button></form></section><aside><h2>Provider Profile</h2><form method="post" class="side-form"><input type="hidden" name="_csrf" value="<?=sk1380_h(sk1380_csrf())?>"><input type="hidden" name="action" value="profile"><label>Display name<input name="display_name" value="<?=sk1380_h($p['display_name'])?>"></label><label>Business name<input name="business_name" value="<?=sk1380_h($p['business_name'])?>"></label><label>Area<input name="area" value="<?=sk1380_h($p['area'])?>"></label><label>Public contact<input name="phone_public" value="<?=sk1380_h($p['phone_public'])?>"></label><label>Bio<textarea name="bio"><?=sk1380_h($p['bio'])?></textarea></label><label class="check"><input type="checkbox" name="fast" value="1" <?=$p['fast_service_enabled']?'checked':''?>> Enable Fast Service</label><button>Save Profile</button></form></aside></div><?php sk1380_end();